// WHAT THIS DOES
// Returns the project description text from project_description.txt.
// If the file is empty, returns "NOT AVAILABLE" so the agent knows not to guess.

// Step 1: read the parsed text file (Extract from File puts the text under "data")
const parsed = $('Parse description').first().json;

// Step 2: take the text, or NOT AVAILABLE if it's missing
let descriptionText = 'NOT AVAILABLE';
if (parsed && parsed.data && String(parsed.data).trim() !== '') {
  descriptionText = String(parsed.data).trim();
}

// Step 3: send it back
return [{ json: { description: descriptionText } }];

// WHAT THIS DOES
// Returns the 8 project phases from project_timeline.csv, with real calendar dates.
// The file only has week numbers, so we convert them using project_start from the config:
//   Phase start date = project start + (start week - 1) weeks
//   Phase end date   = project start + (end week - 1) weeks + 6 days (the Sunday of that week)

// Step 1: settings from the config file
const settings = $('Load settings').first().json.settings;
const oneDay = 24 * 60 * 60 * 1000;

// Step 2: helpers for dates ("2026-03-30" or "3/30/2026" both work)
function toDate(text) {
  const value = String(text).trim();
  if (value.includes('/')) {
    const parts = value.split('/');
    return new Date(Date.UTC(Number(parts[2]), Number(parts[0]) - 1, Number(parts[1])));
  }
  return new Date(value + 'T00:00:00Z');
}
function toText(date) {
  return date.toISOString().slice(0, 10);
}

const projectStart = toDate(settings.project_start);

// Step 3: build one entry per phase
const phases = [];
for (const row of $('Parse timeline').all()) {
  const fileRow = row.json;
  const startWeek = Number(fileRow.start_week);
  const endWeek = Number(fileRow.end_week);

  const startDate = new Date(projectStart.getTime() + (startWeek - 1) * 7 * oneDay);
  const endDate = new Date(projectStart.getTime() + ((endWeek - 1) * 7 + 6) * oneDay);

  phases.push({
    phase: Number(fileRow.phase),
    name: fileRow.phase_name,
    weeks: startWeek + '-' + endWeek,
    start_date: toText(startDate),
    end_date: toText(endDate),
    key_activities: fileRow.key_activities,
    milestones: fileRow.milestones_deliverables
  });
}

// Step 4: send back the list of phases
return [{ json: { project_start: toText(projectStart), phases: phases } }];

// WHAT THIS DOES
// Looks at every task on the board (sample_task_board.csv) and sorts the unfinished ones into 3 lists:
//   blocked  = the task's status is "Blocked"
//   overdue  = the due date has passed and the task isn't Done
//   due_soon = the task isn't Done and is due within due_soon_days (including today)
// The "today" date and the window come from mira_config.json.

// Step 1: settings from the config file
const settings = $('Load settings').first().json.settings;
const windowDays = Number(settings.due_soon_days);
const oneDay = 24 * 60 * 60 * 1000;

// Step 2: helpers for dates ("2026-04-28" or "4/28/2026" both work)
function toDate(text) {
  const value = String(text).trim();
  if (value.includes('/')) {
    const parts = value.split('/');
    return new Date(Date.UTC(Number(parts[2]), Number(parts[0]) - 1, Number(parts[1])));
  }
  return new Date(value + 'T00:00:00Z');
}
function toText(date) {
  return date.toISOString().slice(0, 10);
}
const asOfDate = toDate(settings.as_of_date);

// Step 3: empty lists to fill
const blocked = [];
const overdue = [];
const dueSoon = [];

// Step 4: check each task
for (const row of $('Parse tasks').all()) {
  const task = row.json;

  // Skip finished tasks
  if (task.status === 'Done') {
    continue;
  }

  // How many days until the due date (negative = already past)
  const daysUntilDue = Math.round((toDate(task.due_date) - asOfDate) / oneDay);

  // The basic facts we report for every flagged task
  const info = {
    task_id: task.task_id,
    task_name: task.task_name,
    assignee: task.assignee,
    status: task.status,
    sprint: task.sprint,
    due_date: task.due_date
  };

  if (task.status === 'Blocked') {
    // Use the reason written after "BLOCKED:" in the description, if there is one
    const description = String(task.description || '');
    if (description.includes('BLOCKED:')) {
      info.reason = 'Blocked: ' + description.split('BLOCKED:')[1].trim();
    } else {
      info.reason = 'Status is Blocked';
    }
    blocked.push(info);

  } else if (daysUntilDue < 0) {
    info.days_overdue = -daysUntilDue;
    info.reason = 'Overdue by ' + info.days_overdue + ' days, still ' + task.status;
    overdue.push(info);

  } else if (daysUntilDue <= windowDays) {
    info.days_until_due = daysUntilDue;
    if (daysUntilDue === 0) {
      info.reason = 'Due today, still ' + task.status;
    } else {
      info.reason = 'Due in ' + daysUntilDue + ' days, still ' + task.status;
    }
    dueSoon.push(info);
  }
}

// Step 5: send back the three lists
return [{
  json: {
    as_of: toText(asOfDate),
    window_days: windowDays,
    blocked: blocked,
    overdue: overdue,
    due_soon: dueSoon
  }
}];

// WHAT THIS DOES
// Returns risks R01–R10 from project_risks.csv, with each risk's mitigation tasks,
// a mitigation coverage status, a tier and a rank (PRD §6.4).
// The CODE decides all of this, not the LLM.
//
// WHERE THE LINKS COME FROM: mira_config.json -> risk_mitigation
//   (tasks that reduce each risk + link strength "strong" / "weak"; a PM decision)
//
// HOW:
// 1. Each mitigation task is checked against as_of_date from the config:
//      blocked              = status is Blocked
//      overdue              = past due date and not Done
//      in_progress_due_soon = In Progress and due within due_soon_days
//      todo_due_soon        = To Do and due within due_soon_days (context only)
// 2. Coverage status (answers "which risks have mitigation tasks, and which don't?"):
//      No mitigation      = no tasks linked
//      Weak coverage      = only weak links
//      Mitigation at risk = a strong-linked task is blocked or overdue
//      Covered, on track  = strong link(s), none blocked or overdue
// 3. Tier (for "top N risks"). ONLY STRONG LINKS raise a tier:
//      Tier 1 = a strong-linked task is blocked or overdue
//      Tier 2 = a strong-linked task is In Progress and due now or soon
//      Tier 3 = no urgent signal
// 4. Order: Tier 1, then 2, then 3. Inside Tier 1, blocked ranks above overdue.
//    All other ties keep the risk file order (R01, R02, ...).

// Step 1: settings from the config file
const settings = $('Load settings').first().json.settings;
const mitigationLinks = settings.risk_mitigation || {};
const windowDays = Number(settings.due_soon_days);
const oneDay = 24 * 60 * 60 * 1000;

// Step 2: helpers for dates ("2026-04-28" or "4/28/2026" both work)
function toDate(text) {
  const value = String(text).trim();
  if (value.includes('/')) {
    const parts = value.split('/');
    return new Date(Date.UTC(Number(parts[2]), Number(parts[0]) - 1, Number(parts[1])));
  }
  return new Date(value + 'T00:00:00Z');
}
function toText(date) {
  return date.toISOString().slice(0, 10);
}
const asOfDate = toDate(settings.as_of_date);

// Step 3: put all tasks in a lookup table by task ID, e.g. tasksById['T024']
const tasksById = {};
for (const row of $('Parse tasks').all()) {
  tasksById[row.json.task_id] = row.json;
}

// Step 4: a helper that describes one mitigation task and its live signal
function checkTask(taskId) {
  const task = tasksById[taskId];
  if (!task) {
    return { task_id: taskId, task_name: 'NOT FOUND ON BOARD', status: 'UNKNOWN', signal: 'none' };
  }
  const result = {
    task_id: taskId,
    task_name: task.task_name,
    status: task.status,
    due_date: task.due_date,
    signal: 'none'
  };
  if (task.status === 'Done') {
    return result;
  }
  const daysUntilDue = Math.round((toDate(task.due_date) - asOfDate) / oneDay);
  if (task.status === 'Blocked') {
    result.signal = 'blocked';
  } else if (daysUntilDue < 0) {
    result.signal = 'overdue';
    result.days_overdue = -daysUntilDue;
  } else if (daysUntilDue <= windowDays) {
    if (task.status === 'In Progress') {
      result.signal = 'in_progress_due_soon';
    } else {
      result.signal = 'todo_due_soon';
    }
    result.days_until_due = daysUntilDue;
  }
  return result;
}

// Step 5: build one entry per risk
const risks = [];
let fileOrder = 0;
for (const row of $('Parse risks').all()) {
  const risk = row.json;

  // 5a. Mitigation tasks and link strength from the config
  let linkedTaskIds = [];
  let strength = 'none';
  const link = mitigationLinks[risk.risk_id];
  if (link) {
    linkedTaskIds = link.tasks || [];
    strength = link.strength || 'none';
  }
  if (linkedTaskIds.length === 0) {
    strength = 'none';
  }

  const mitigationTasks = [];
  for (const taskId of linkedTaskIds) {
    mitigationTasks.push(checkTask(taskId));
  }

  // 5b. What signals do the mitigation tasks show?
  let hasBlocked = false;
  let hasOverdue = false;
  let hasInProgressSoon = false;
  for (const t of mitigationTasks) {
    if (t.signal === 'blocked') hasBlocked = true;
    if (t.signal === 'overdue') hasOverdue = true;
    if (t.signal === 'in_progress_due_soon') hasInProgressSoon = true;
  }

  // 5c. Coverage status
  let coverage = 'Covered, on track';
  if (strength === 'none') {
    coverage = 'No mitigation';
  } else if (strength === 'weak') {
    coverage = 'Weak coverage';
  } else if (hasBlocked || hasOverdue) {
    coverage = 'Mitigation at risk';
  }

  // 5d. Tier: only strong links can raise it
  let tier = 3;
  if (strength === 'strong') {
    if (hasBlocked || hasOverdue) {
      tier = 1;
    } else if (hasInProgressSoon) {
      tier = 2;
    }
  }

  // 5e. Sort number: tier first, then (inside Tier 1) blocked before overdue, then file order
  let sortNumber = tier * 100 + fileOrder;
  if (tier === 1 && !hasBlocked) {
    sortNumber = sortNumber + 50;
  }

  risks.push({
    risk_id: risk.risk_id,
    category: risk.category,
    risk: risk.risk_challenge,
    impact: risk.impact,
    mitigation: risk.mitigation_strategy,
    mitigation_tasks: mitigationTasks,
    link_strength: strength,
    coverage_status: coverage,
    tier: tier,
    sortNumber: sortNumber
  });
  fileOrder = fileOrder + 1;
}

// Step 6: sort, then number the ranks 1, 2, 3, ...
risks.sort(function (a, b) {
  return a.sortNumber - b.sortNumber;
});
for (let i = 0; i < risks.length; i++) {
  risks[i].rank = i + 1;
  delete risks[i].sortNumber;
}

// Step 7: send back the ranked list
return [{
  json: {
    as_of: toText(asOfDate),
    ranking_rule: 'Tier 1 = strong-linked task blocked/overdue (blocked first), Tier 2 = strong-linked task in progress and due soon, Tier 3 = no signal. Weak links never raise a tier.',
    risks: risks
  }
}];

// WHAT THIS DOES
// Returns task rows from sample_task_board.csv, optionally filtered by sprint and/or status,
// PLUS exact counts by status for those tasks (Done, In Progress, Blocked, To Do, total).
//   sprint: e.g. "Sprint 3" or just "3"; any text containing "current" = current_sprint
//           from mira_config.json (empty = all sprints)
//   status: Done, In Progress, Blocked or To Do  (empty = all statuses)
// The CODE does the counting so the numbers are always exact (the LLM never counts).
// If nothing matches, it returns an empty list and says so, so the agent doesn't guess.

// Step 1: read the request and settings (from "Load settings")
const request = $('Load settings').first().json;
const settings = request.settings;
let sprintFilter = String(request.sprint || '').trim();
const statusFilter = String(request.status || '').trim().toLowerCase();

// "current", "current sprint", "the current sprint" ... all mean the sprint set in the config file
if (sprintFilter.toLowerCase().includes('current')) {
  sprintFilter = String(settings.current_sprint || '');
}

// Accept "3" as well as "Sprint 3"
if (sprintFilter !== '' && !sprintFilter.toLowerCase().startsWith('sprint')) {
  sprintFilter = 'Sprint ' + sprintFilter;
}

// Step 2: start every count at zero
const counts = {
  'Done': 0,
  'In Progress': 0,
  'Blocked': 0,
  'To Do': 0,
  'total': 0
};

// Step 3: keep only the tasks that match the filters, and count them
const tasks = [];
for (const row of $('Parse tasks').all()) {
  const task = row.json;

  if (sprintFilter !== '' && String(task.sprint).toLowerCase() !== sprintFilter.toLowerCase()) {
    continue;
  }
  if (statusFilter !== '' && String(task.status).toLowerCase() !== statusFilter) {
    continue;
  }

  tasks.push({
    task_id: task.task_id,
    task_name: task.task_name,
    status: task.status,
    assignee: task.assignee,
    priority: task.priority,
    sprint: task.sprint,
    due_date: task.due_date,
    description: task.description
  });

  if (counts[task.status] !== undefined) {
    counts[task.status] = counts[task.status] + 1;
  }
  counts.total = counts.total + 1;
}

// Step 4: describe what was asked for, so the answer is clear
let sprintText = 'all sprints';
if (sprintFilter !== '') {
  sprintText = sprintFilter;
}
let statusText = 'all statuses';
if (statusFilter !== '') {
  statusText = request.status;
}

let note = 'Found ' + tasks.length + ' task(s).';
if (tasks.length === 0) {
  note = 'No tasks found for ' + sprintText + ', ' + statusText + '. Do not invent tasks.';
}

// Step 5: send back the counts and the matching tasks
return [{
  json: {
    as_of: settings.as_of_date,
    current_sprint: settings.current_sprint,
    filters: { sprint: sprintText, status: statusText },
    counts: counts,
    note: note,
    tasks: tasks
  }
}];

// WHAT THIS DOES
// Lists the timeline milestones (project_timeline.csv) that are due in the next
// milestone_window_days after as_of_date (both from mira_config.json).
// A milestone is due on its phase's end date. Week numbers become dates using project_start.
// The timeline has no "done" column, so this tool does not judge whether a milestone is complete.

// Step 1: settings from the config file
const settings = $('Load settings').first().json.settings;
const windowDays = Number(settings.milestone_window_days);
const oneDay = 24 * 60 * 60 * 1000;

// Step 2: helpers for dates ("2026-04-28" or "4/28/2026" both work)
function toDate(text) {
  const value = String(text).trim();
  if (value.includes('/')) {
    const parts = value.split('/');
    return new Date(Date.UTC(Number(parts[2]), Number(parts[0]) - 1, Number(parts[1])));
  }
  return new Date(value + 'T00:00:00Z');
}
function toText(date) {
  return date.toISOString().slice(0, 10);
}
const asOfDate = toDate(settings.as_of_date);
const projectStart = toDate(settings.project_start);
const windowEnd = new Date(asOfDate.getTime() + windowDays * oneDay);

// Step 3: check each phase's due date
const upcoming = [];
for (const row of $('Parse timeline').all()) {
  const phase = row.json;
  const endWeek = Number(phase.end_week);
  const dueDate = new Date(projectStart.getTime() + ((endWeek - 1) * 7 + 6) * oneDay);
  const daysUntilDue = Math.round((dueDate - asOfDate) / oneDay);

  if (daysUntilDue >= 0 && daysUntilDue <= windowDays) {
    upcoming.push({
      phase: Number(phase.phase),
      phase_name: phase.phase_name,
      milestones: phase.milestones_deliverables,
      due_date: toText(dueDate),
      days_until_due: daysUntilDue
    });
  }
}

// Step 4: send back the list (empty list = no milestones in the window)
let note = 'Found ' + upcoming.length + ' milestone(s) due in the window.';
if (upcoming.length === 0) {
  note = 'No milestones are due in this window. Do not invent milestones.';
}

return [{
  json: {
    as_of: toText(asOfDate),
    window: toText(asOfDate) + ' to ' + toText(windowEnd),
    note: note,
    upcoming: upcoming
  }
}];

// WHAT THIS DOES
// Runs once at the start of every Mira Tools call, after all files are downloaded and parsed.
// It combines the request (which tool, sprint, status) with Mira's own settings
// from mira_config.json, and passes them on to the Switch.
// No project facts live in code: dates, windows and mitigation links all come from the config file.

// Step 1: the request sent by the agent
const request = $('When Executed by Another Workflow').first().json;

// Step 2: the parsed config file (Extract from File puts it under "data")
const parsed = $('Parse config').first().json;
let config = parsed;
if (parsed.data) {
  config = parsed.data;
}

// Step 3: pass the request and the settings on to the Switch
return [{
  json: {
    tool: request.tool,
    sprint: request.sprint,
    status: request.status,
    settings: config
  }
}];
